d=[shot(p[1],4,'固定诊所入口物件近景，牌匾在画面左侧，木柱占中央，右侧门帘垂直落下，木纹清楚。','入口保持安静，画外的春子带着不满问出一句，门帘下缘随空气轻轻一动，随后落稳。','木柱采用灰棕木色，牌匾淡木色，医疗十字标志为深色，右侧门帘为米灰色。','春子画外说：“何を笑ってるの？”（平直而不满，像已经注意对方一阵了。）','入口上方柔光照亮浅木牌，柱缝留暗，帘面有柔和竖向明暗。','洞窟远处空气声，门帘轻擦。',speech=3,acting=0,scene='临时诊所外'),shot(p[2],4,'固定双人肩上中近景，春子背面长发占左前，青在右前回望，尖耳与微笑清楚，双手和浅布在右下。','青听到问话扭头回望，脸上的笑来不及收。她先吃惊地反问，接着急忙否认，手里的浅布被捏紧一点；春子留在左前听着，青的笑却仍残在嘴角。','灰棕木门竖纹在后层，右侧一小段深褐岩壁，近处发束与远处木门分开。','青说：“えっ？！笑ってないよ！”（先吃惊，后句急着否认，轻快里带一点心虚。）',LIGHT,'布料被捏紧时轻擦，洞窟底声持续。',speech=3.2,scene='临时诊所外'),shot(p[3],4,'固定春子正面头肩近景，脸在画面中央，右脸颊肿起，深色罩衫从下缘裁切，焦点落在半垂双眼。','春子沉着脸看着前方，把青还在笑的事实直接点出来。她嘴唇短短开合，语气说得平，眼神却一点也没松；肿起的脸颊始终绷着，话后仍等解释。','诊所入口灰棕木墙面构成背景，竖向木纹低对比，人物轮廓清楚。','春子说：“今だって、まだ笑ってるじゃん。”（不满、冷淡，重音轻落在「今だって」。）',LIGHT,AIR,speech=3.2,scene='临时诊所外',background_mode='continuity',background_refs=['第19話_08_003.jpg'])]
